  gorsel: `<svg viewBox="0 0 560 190" role="img" aria-label="Sınıf panosunda element ipuçları yazan dört kart"><g fill="var(--dolgu)" stroke="currentColor" stroke-width="1.5"><rect x="10" y="10" width="260" height="80" rx="10"/><rect x="290" y="10" width="260" height="80" rx="10"/><rect x="10" y="100" width="260" height="80" rx="10"/><rect x="290" y="100" width="260" height="80" rx="10"/></g><g fill="none" stroke="var(--vurgu)" stroke-width="2.5"><circle cx="36" cy="50" r="15"/><circle cx="316" cy="50" r="15"/><circle cx="36" cy="140" r="15"/><circle cx="316" cy="140" r="15"/></g><g fill="currentColor" font-size="16" font-weight="bold" text-anchor="middle"><text x="36" y="56">1</text><text x="316" y="56">2</text><text x="36" y="146">3</text><text x="316" y="146">4</text></g><g fill="currentColor" font-size="15"><text x="62" y="56">3. periyodun ilk elementi</text><text x="342" y="56">2. periyodun son elementi</text><text x="62" y="135">Atom numarası 12 olan</text><text x="62" y="157">element</text><text x="342" y="146">1. periyodun son elementi</text></g></svg>`,
  secenekler: ["1 ve 2", "1 ve 3", "2 ve 4", "3 ve 4"],
