  gorsel: `<svg viewBox="0 0 550 150" role="img" aria-label="Periyodik tablonun ilk dört periyodunda yıldız, kare, daire ve üçgen sembolleriyle işaretli dört kutu"><g stroke="currentColor" stroke-width="1.2"><rect x="14" y="10" width="29" height="32" fill="none"/><rect x="507" y="10" width="29" height="32" fill="none"/><rect x="14" y="42" width="29" height="32" fill="none"/><rect x="43" y="42" width="29" height="32" fill="none"/><rect x="362" y="42" width="29" height="32" fill="none"/><rect x="391" y="42" width="29" height="32" fill="none"/><rect x="420" y="42" width="29" height="32" fill="none"/><rect x="449" y="42" width="29" height="32" fill="none"/><rect x="478" y="42" width="29" height="32" fill="none"/><rect x="507" y="42" width="29" height="32" fill="none"/><rect x="14" y="74" width="29" height="32" fill="none"/><rect x="43" y="74" width="29" height="32" fill="none"/><rect x="362" y="74" width="29" height="32" fill="none"/><rect x="391" y="74" width="29" height="32" fill="none"/><rect x="420" y="74" width="29" height="32" fill="none"/><rect x="449" y="74" width="29" height="32" fill="none"/><rect x="478" y="74" width="29" height="32" fill="none"/><rect x="507" y="74" width="29" height="32" fill="none"/><rect x="14" y="106" width="29" height="32" fill="none"/><rect x="43" y="106" width="29" height="32" fill="none"/><rect x="72" y="106" width="29" height="32" fill="none"/><rect x="101" y="106" width="29" height="32" fill="none"/><rect x="130" y="106" width="29" height="32" fill="none"/><rect x="159" y="106" width="29" height="32" fill="none"/><rect x="188" y="106" width="29" height="32" fill="none"/><rect x="217" y="106" width="29" height="32" fill="none"/><rect x="246" y="106" width="29" height="32" fill="none"/><rect x="275" y="106" width="29" height="32" fill="none"/><rect x="304" y="106" width="29" height="32" fill="none"/><rect x="333" y="106" width="29" height="32" fill="none"/><rect x="362" y="106" width="29" height="32" fill="none"/><rect x="391" y="106" width="29" height="32" fill="none"/><rect x="420" y="106" width="29" height="32" fill="none"/><rect x="449" y="106" width="29" height="32" fill="none"/><rect x="478" y="106" width="29" height="32" fill="none"/><rect x="507" y="106" width="29" height="32" fill="none"/></g><polygon points="57.5,48.5 59.9,54.8 66.5,55.1 61.3,59.2 63.1,65.7 57.5,62.0 51.9,65.7 53.7,59.2 48.5,55.1 55.1,54.8" fill="currentColor"/><rect x="50.5" y="115" width="14" height="14" fill="currentColor"/><circle cx="463.5" cy="90" r="7.5" fill="currentColor"/><polygon points="376.5,114 384.5,129 368.5,129" fill="currentColor"/></svg>`,
